pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address attacker, address target, uint256 amount) public {
        vm.assume(attacker != c.owner());
        vm.assume(attacker != address(0));
        vm.assume(target != address(c));
        vm.assume(amount > 0);

        vm.deal(attacker, amount);
        vm.prank(attacker);
        bool ok = true;
        try c.sendMoney(target, amount) {
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}
